import{t as e}from"./jsx-runtime-CY_jTiqj.js";import{r as t}from"./ThemeToggle-vCpx62jE.js";import{t as n}from"./braces-Du93lkpt.js";import{C as r,D as i,E as a,I as o,L as s,M as c,N as l,P as u,S as d,b as f,k as p,l as m,n as h,o as g,t as _,w as v}from"./shared-BLp3PbbW.js";import{t as y}from"./shield-check-DLlmt4Nd.js";import{t as b}from"./CodeEditor-DqHMt3P8.js";var x=t(`FileInput`,[[`path`,{d:`M4 22h14a2 2 0 0 0 2-2V7l-5-5H6a2 2 0 0 0-2 2v4`,key:`1pf5j1`}],[`path`,{d:`M14 2v4a2 2 0 0 0 2 2h4`,key:`tnqrlb`}],[`path`,{d:`M2 15h10`,key:`jfw4w8`}],[`path`,{d:`m9 18 3-3-3-3`,key:`112psh`}]]),S=e();function C({module:e}){return(0,S.jsxs)(l,{children:[(0,S.jsx)(c,{chip:`Блок 10 · модель TaskCreate`,title:`Модель входящего JSON`,intro:`Впервые опишем входные поля с помощью Pydantic и проверим модель до подключения POST.`,variant:`project`,tags:[{icon:(0,S.jsx)(x,{size:15}),label:`входная схема`},{icon:(0,S.jsx)(n,{size:15}),label:`JSON body`},{icon:(0,S.jsx)(y,{size:15}),label:`проверка до handler`}]}),(0,S.jsxs)(u,{number:`00`,title:`Зачем описывать вход отдельно`,children:[(0,S.jsx)(`p`,{children:"В добавлении query-параметров мы читали Planner через `GET /tasks`. Теперь подготовим данные для будущего создания задачи. Это первое объяснение `BaseModel` в текущей последовательности: старый материал с другим номером не означает, что именно этот ученик уже изучил Pydantic."}),(0,S.jsx)(p,{variant:`connected`,items:[{title:`Что уже планировалось изучить`,description:`JSON-строка и JSON-число, body запроса, класс Task и чтение Planner. Перед работой это проверяют в проекте ученика.`},{title:`Новый вопрос`,description:`Как описать только клиентские данные и заметить пропущенное поле или неподходящий тип?`},{title:`Результат`,description:`Одна TaskCreate с обязательными title и priority, проверенная прямым созданием в Python.`}]}),(0,S.jsxs)(`p`,{children:["В запросе клиент сообщает название и приоритет. Он не должен назначать номер записи или начальный статус: это ответственность приложения. Поэтому полная предметная `Task` и входная модель запроса описывают разные данные, даже если у них есть общие поля. Например, в JSON ",(0,S.jsx)(`code`,{children:`{"title":"Прочитать API","priority":4}`}),` название является строкой, а приоритет является числом. Сам факт, что эти значения записаны в одном объекте JSON, ещё не превращает их в предметную задачу Planner и не сохраняет их в файл.`]}),(0,S.jsxs)(s,{children:[(0,S.jsx)(o,{badge:`ВХОД`,title:`TaskCreate`,code:`title: str\\npriority: int`,children:`Два значения от клиента. Модель проверяет форму данных и создаёт объект в памяти.`}),(0,S.jsx)(o,{badge:`ЗАПИСЬ PLANNER`,title:`Task`,code:`id · title · priority · is_done · tags`,children:`Полная предметная запись. Сервис позднее создаст её и задаст серверные поля.`})]}),(0,S.jsx)(`p`,{children:"Представьте бланк заявки: человек заполняет только известные ему поля, а внутренний номер добавляет система учёта. Это сравнение помогает определить роли данных, но не является механизмом Pydantic: сам бланк ничего не проверяет и не сохраняет. В коде границу задаёт отдельный класс. Если описать во входной модели `id`, клиент сможет прислать такое значение, хотя назначать его должен Planner. Если убрать `priority`, сервису позже не хватит одного из обязательных клиентских значений. Состав полей поэтому отражает именно договор между клиентом и будущим обработчиком."}),(0,S.jsx)(_,{caption:`Граница текущего занятия и следующего шага`,children:(0,S.jsxs)(g,{label:`От входных данных к будущему созданию задачи`,children:[(0,S.jsx)(m,{title:`JSON body`,shape:`process`,children:(0,S.jsx)(`p`,{children:`клиентские title и priority`})}),(0,S.jsx)(h,{label:`сейчас: разобрать и проверить`}),(0,S.jsx)(m,{title:`TaskCreate`,children:(0,S.jsx)(`p`,{children:`объект в памяти или ValidationError`})}),(0,S.jsx)(h,{label:`позже, при создании задачи`,lineStyle:`dashed`}),(0,S.jsx)(m,{title:`POST → сервис`,shape:`terminator`,children:(0,S.jsx)(`p`,{children:`создание и сохранение здесь не выполняются`})})]})}),(0,S.jsx)(`p`,{children:"Сегодня мы останавливаемся на проверенной модели. Не вызываем `add_task`, не отправляем HTTP-запрос и не меняем JSON-файл. При прямом создании `TaskCreate` появляется только объект Python; запись возникнет лишь после будущего вызова сервиса."})]}),(0,S.jsxs)(u,{number:`01`,title:`Как BaseModel использует поля класса`,children:[(0,S.jsx)(`p`,{children:"Аннотация в простом классе сообщает читателю тип, но сама по себе не проверяет переданные значения. `BaseModel` из Pydantic добавляет поведение при создании экземпляра: библиотека сопоставляет входные значения с объявленными полями, разбирает их и либо возвращает объект, либо сообщает об ошибке проверки."}),(0,S.jsx)(b,{caption:`Независимый пример для знакомства с синтаксисом`,code:`from pydantic import BaseModel


class Review(BaseModel):
    message: str
    stars: int


review = Review(message="Полезно", stars=5)
print(review.message)
print(review.stars)`}),(0,S.jsx)(`p`,{children:"Сначала Python создаёт класс `Review`, унаследованный от `BaseModel`. Записи `message: str` и `stars: int` объявляют поля. Затем вызов `Review(...)` передаёт значения для этих полей; после успешной проверки их можно читать как атрибуты: `review.message` и `review.stars`. Имя класса и имя объекта здесь различаются. `Review`: описание, по которому можно создавать объекты; `review`: один конкретный объект с переданными значениями. Двоеточие связывает имя поля с ожидаемым типом, а не присваивает полю значение. Значения появляются во время вызова конструктора модели."}),(0,S.jsx)(`p`,{children:'Оба поля обязательны, потому что после двоеточия нет значения по умолчанию. Если написать `stars: int = 5`, вызов без `stars` получит значение 5 и поле станет необязательным для создания. Нам такой вариант не подходит: клиент должен явно прислать оба значения. Поэтому в `TaskCreate` не добавляем `= ...`. Проверьте это на примере: `Review(message="Полезно")` не содержит данных для `stars`, поэтому полного объекта с двумя полями создать нельзя. Ошибка возникает при создании модели; она не означает, что сломан файл Planner или что нужно добавить пустое значение в хранилище.'}),(0,S.jsx)(f,{question:`Какое значение будет у review.stars после Review(message="Полезно", stars=5)?`,options:[`Атрибут со значением 5`,`Только описание типа int`,`Новая запись в Planner`],correctIndex:0,explanation:`Успешное создание экземпляра связывает переданное значение с полем stars. Review не связан с Planner и ничего там не сохраняет.`}),(0,S.jsx)(`p`,{children:"Теперь перенесём знакомую конструкцию на вход будущего API. Сначала найдите существующий `app/api.py` и проверьте, нет ли там подходящей `TaskCreate`. Если она уже есть, не объявляйте второй класс. Если её нет, добавьте схему рядом с другими моделями и до маршрутов. Существующие GET-маршруты оставьте без изменений. Наличие файла и маршрутов нужно подтвердить именно в рабочей копии: план занятия описывает учебную цель, но не доказывает текущее состояние проекта. Если структура проекта отличается, остановитесь на найденном API-модуле и сохраните существующую архитектуру."}),(0,S.jsx)(v,{title:`Восстановите минимальную схему`,prompt:`Расположите импорт, объявление класса и два обязательных поля. Не добавляйте поля полной Task или ограничение диапазона.`,pieces:[{id:`import`,code:`from pydantic import BaseModel`},{id:`class`,code:`class TaskCreate(BaseModel):`},{id:`title`,code:`    title: str`},{id:`priority`,code:`    priority: int`},{id:`id`,code:`    id: int`,note:`назначает Planner`},{id:`field`,code:`    priority: int = Field(ge=1, le=5)`,note:`предметное ограничение вне этой схемы`}],correctOrder:[`import`,`class`,`title`,`priority`],explanation:`Схема содержит два обязательных клиентских поля. id назначает Planner; диапазон приоритета относится к предметным правилам и здесь не вводится.`,incorrectExplanation:`Оставьте импорт, класс и два поля без значений по умолчанию. Уберите id и Field: они выходят за контракт этого занятия.`}),(0,S.jsx)(a,{tone:`info`,children:`Код схемы не является обработчиком. Он только объявляет, какие значения модель ожидает при создании экземпляра.`})]}),(0,S.jsxs)(u,{number:`02`,title:`Проверка типа и предметное правило: не одно и то же`,children:[(0,S.jsx)(`p`,{children:'При создании `TaskCreate` Pydantic проверяет и разбирает значения полей. В обычном режиме строка `"4"` может быть преобразована в целое число 4. Поэтому после создания смотрите не только на исходный ввод, но и на значение и тип атрибута. Например, в JSON строка записана с кавычками (`"4"`), а число записывают без них (`4`). После разбора оба варианта могут дать атрибут `priority` со значением целого типа. Это преобразование происходит потому, что модель ожидает `int`; оно не меняет исходный JSON-файл и не означает, что Planner принял новую задачу.'}),(0,S.jsx)(f,{question:`Что покажет type(model.priority).__name__ для TaskCreate(title="Повторить API", priority="4") в обычном режиме?`,options:[`str: исходное значение всегда остаётся строкой`,`int: Pydantic преобразует числовую строку`,`HTTPException: прямой вызов уже является запросом`],correctIndex:1,explanation:`Pydantic разбирает строку с числом как int. Это прямое создание объекта, не HTTP-запрос; HTTP-статуса здесь нет.`}),(0,S.jsx)(`p`,{children:"Аннотация `priority: int` описывает тип, а не допустимый диапазон. Значение `0` является целым число, поэтому сама эта схема не задаёт правило «от 1 до 5». Такое предметное ограничение проверяет `Task` или сервис. Мы не добавляем `Field`, валидаторы или строгий режим: это изменило бы заданный план. Полезно разделять вопросы по порядку: «можно ли представить это значение как целое число?» и «разрешает ли Planner такой приоритет?». На первый вопрос отвечает тип поля; второй вопрос касается предметного правила. Успешный ответ на первый вопрос не гарантирует успешный ответ на второй."}),(0,S.jsx)(d,{statement:(0,S.jsx)(S.Fragment,{children:"Если `TaskCreate` приняла `priority=0`, значит модель проверила и одобрила все правила Planner."}),isTrue:!1,explanation:`Модель с аннотацией int проверяет тип, но не диапазон 1–5. Предметное правило применяется на другом уровне.`}),(0,S.jsx)(`p`,{children:"Проверим три исхода в проектной `.venv`: обычное число, преобразуемую строку и два некорректных случая. Перед запуском импортируйте `TaskCreate` из `app.api`. В прямом вызове передаём именованные аргументы Python; проверка JSON-текста через HTTP появится в следующем занятии, когда модель будет подключена к body. Именованный аргумент `priority=4` передаёт значение непосредственно конструктору Python. Это полезная изолированная проба: мы проверяем поведение схемы, не поднимая сервер и не смешивая результат с маршрутом, HTTP-ответом или записью на диск."}),(0,S.jsx)(b,{caption:`Прямое создание модели в Python`,code:`from app.api import TaskCreate
from pydantic import ValidationError

number = TaskCreate(title="Проверить вход", priority=4)
text_number = TaskCreate(title="Проверить вход", priority="4")
print(number.priority, type(number.priority).__name__)
print(text_number.priority, type(text_number.priority).__name__)

for values in [
    {"title": "Проверить вход"},
    {"title": None, "priority": 4},
]:
    try:
        TaskCreate(**values)
    except ValidationError as error:
        print(error)`}),(0,S.jsx)(`p`,{children:"Первые две строки должны показать `4 int`. В первом ошибочном словаре нет обязательного `priority`; во втором `None` не является строкой `title`. Оба случая не дают экземпляр и приводят к `ValidationError`. Точный текст сообщения может различаться между версиями, поэтому найдите в нём название поля и причину, а не заучивайте формулировку. Для пропущенного поля ищите указание на `priority` и отсутствие значения; для второго случая ищите указание на `title` и несовместимое значение. Так можно проверить саму причину, даже если библиотека меняет подробности текста."}),(0,S.jsx)(`p`,{children:`При прямом вызове Pydantic исключение остаётся ошибкой Python. Когда FastAPI получит эту модель как тело запроса, он остановит обработку некорректного body и вернёт HTTP 422 до выполнения функции маршрута. Число 422 является ответом HTTP-слоя, а не типом исключения при прямом создании. В этом занятии мы не пишем обработчик и не отправляем запрос.`})]}),(0,S.jsxs)(u,{number:`03`,title:`Где заканчивается TaskCreate`,children:[(0,S.jsx)(`p`,{children:"Поля схемы выбирают по роли данных. Клиент сообщает `title` и `priority`. `id`, начальный `is_done` и внутренние данные появляются у полной `Task`, которую создаёт Planner. Если добавить серверные поля во входной контракт, клиенту придётся задавать значения, которыми должен управлять сам сервер. Входная модель не обязана копировать все атрибуты предметного объекта: она описывает только сведения, которые доступны и нужны на границе запроса. Серверные значения могут зависеть от состояния проекта или внутренних правил, поэтому их назначают позже, при создании `Task`."}),(0,S.jsx)(r,{code:`class TaskCreate(BaseModel):
    title: str
    priority: int
    id: int
    is_done: bool = False`,question:`Какие строки нарушают роль входной модели и почему?`,options:[`title и priority: это значения клиента`,`id и is_done: ими должен управлять Planner`,`Ни одна: входная схема обязана повторять всю Task`],correctIndex:1,explanation:`TaskCreate описывает только клиентскую часть. Planner назначит id и начальное состояние при создании полной Task.`,fix:`class TaskCreate(BaseModel):
    title: str
    priority: int`}),(0,S.jsx)(`p`,{children:"Исправленный класс всё ещё не создаёт задачу. Он даёт проверенный объект входных данных, который следующее занятие передаст в `PlannerService.add_task`. Именно сервис применит предметные правила и создаст полную запись; модель не пишет в файл. Разделение упрощает поиск ошибок: проблема отсутствующего `priority` относится к форме входа, а отказ из-за недопустимого приоритета относится к правилам задачи. У этих проверок разные причины и разные места выполнения."}),(0,S.jsx)(a,{children:`Сейчас: схема и прямые проверки в Python. При создании задачи: POST, вызов сервиса и сохранение. Не переносите будущий маршрут в этот шаг.`})]}),(0,S.jsxs)(u,{number:`04`,title:`Самостоятельная проверка в проекте`,children:[(0,S.jsx)(`p`,{children:"Откройте тот же проект StudyHub, где находятся `app/api.py` и `.venv`. Сначала установите фактическое состояние класса. Если подходящая `TaskCreate` уже объявлена, проверьте её и сохраните; если нет, добавьте один класс с `title: str` и `priority: int`. Не создавайте второй модуль, окружение или список задач. Перед редактированием посмотрите на импорты и окружающие маршруты, чтобы встроить схему в существующий модуль, а не затереть работу, выполненную ранее. При проверке используйте именно интерпретатор этого проекта: другая установка Pydantic может вести себя иначе."}),(0,S.jsx)(p,{variant:`connected`,items:[{title:`Осмотрите точку входа`,description:`Найдите app/api.py и существующую TaskCreate. Зафиксируйте, требуется ли правка.`},{title:`Проверьте объект`,description:`В той же .venv сравните priority=4 и priority="4", затем пропущенный priority и title=None.`},{title:`Сверьте границы`,description:`Убедитесь, что GET и данные Planner не менялись, а POST не добавлен.`}]}),(0,S.jsx)(b,{caption:`Запуск Python из корня проекта в PowerShell`,code:`.\\\\.venv\\\\Scripts\\\\python.exe`}),(0,S.jsx)(`p`,{children:"Результат можно проверить по наблюдаемым признакам: существует ровно одна подходящая модель; оба поля обязательны; число и преобразуемая строка дают целый атрибут; пропуск поля и `title=None` показывают `ValidationError`; маршруты, сервис и JSON остались без изменений. Этот результат передаётся для POST как входная схема. Для самостоятельного объяснения сформулируйте три вывода: какие поля присылает клиент, в какой момент Pydantic создаёт объект и чем ошибка прямого создания отличается от HTTP 422. Если один из ответов пока не получается, вернитесь к соответствующей пробе выше и сопоставьте вход с результатом."})]}),(0,S.jsx)(i,{points:[(0,S.jsx)(`span`,{children:"`TaskCreate`: Pydantic-модель двух обязательных клиентских полей."},`shape`),(0,S.jsx)(`span`,{children:"Успешное создание даёт объект с атрибутами; ошибка даёт `ValidationError`."},`object`),(0,S.jsx)(`span`,{children:'Pydantic может преобразовать строку `"4"` в `int`; тип не задаёт диапазон 1–5.'},`conversion`),(0,S.jsx)(`span`,{children:"`TaskCreate` не содержит серверный `id`, не вызывает сервис и не сохраняет запись."},`roles`),(0,S.jsx)(`span`,{children:`Проверенная модель станет body для POST и будет передана сервису.`},`next`)]})]})}export{C as Lesson50};